import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.BCectEOt.js";const f=JSON.parse('{"title":"常见问题","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hans/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hans/faq/"}],["meta",{"property":"og:title","content":"常见问题 | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Monster Hunter reference data and armor builds for Wilds, Rise with Sunbreak, and World with Iceborne."}]]},"headers":[],"relativePath":"zh-hans/faq/index.md","filePath":"zh-hans/faq/index.md"}'),n={name:"zh-hans/faq/index.md"};function i(h,a,d,s,l,p){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="支持哪些游戏" tabindex="-1">支持哪些游戏？ <a class="header-anchor" href="#支持哪些游戏" aria-label="Permalink to &quot;支持哪些游戏？&quot;">​</a></h2><p>支持《怪物猎人：荒野》《崛起＋曙光》与《世界＋冰原》。各游戏使用独立资料，可在应用首页切换并查看对应内容。</p><h2 id="现在可以下载吗" tabindex="-1">现在可以下载吗？ <a class="header-anchor" href="#现在可以下载吗" aria-label="Permalink to &quot;现在可以下载吗？&quot;">​</a></h2><p>iOS、Android 与鸿蒙版正在开发中，尚无公开的商店页面。正式上架后，<a href="./../#download">下载应用</a>区域将提供商店链接。</p><h2 id="是否支持离线使用" tabindex="-1">是否支持离线使用？ <a class="header-anchor" href="#是否支持离线使用" aria-label="Permalink to &quot;是否支持离线使用？&quot;">​</a></h2><p>支持。图鉴资料随应用内置，浏览、搜索、收藏与配装搜索均在本地执行。访问外部网站或下载应用更新时需要网络连接。</p><h2 id="配装搜索支持哪些条件" tabindex="-1">配装搜索支持哪些条件？ <a class="header-anchor" href="#配装搜索支持哪些条件" aria-label="Permalink to &quot;配装搜索支持哪些条件？&quot;">​</a></h2><p>可设定目标技能与等级，固定或排除指定装备，并按已持有的装饰品数量筛选防具组合。《崛起》还支持自有护石与怪异炼化防具。</p><p>搜索结果取决于当前游戏资料与所设条件。配装搜索目前不包含伤害计算功能。</p><h2 id="支持哪些语言" tabindex="-1">支持哪些语言？ <a class="header-anchor" href="#支持哪些语言" aria-label="Permalink to &quot;支持哪些语言？&quot;">​</a></h2><p>支持简体中文、繁体中文、英语与日语。尚未提供翻译的内容会显示英文。网站截图与页面语言保持一致，应用内也可选择语言。</p><h2 id="这是-capcom-官方应用吗" tabindex="-1">这是 CAPCOM 官方应用吗？ <a class="header-anchor" href="#这是-capcom-官方应用吗" aria-label="Permalink to &quot;这是 CAPCOM 官方应用吗？&quot;">​</a></h2><p>不是。苍蓝星图鉴是由爱好者独立开发的非商业应用，与 CAPCOM 无关联，亦未获其认可或支持。Monster Hunter 的游戏美术与数据归 CAPCOM Co., Ltd. 所有。</p><h2 id="如何参与资料完善" tabindex="-1">如何参与资料完善？ <a class="header-anchor" href="#如何参与资料完善" aria-label="Permalink to &quot;如何参与资料完善？&quot;">​</a></h2><p>欢迎协助核对游戏资料与翻译，详情请参阅<a href="./../others/">关于与支持</a>。报告资料问题时，请注明游戏、怪物或装备名称、具体问题及可核实的来源。</p>',16)])])}const u=e(n,[["render",i]]);export{f as __pageData,u as default};
